window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[221]={"id":"221","numero":221,"titre":"Athérome — polyathéromateux","objectifs":[{"id":"221-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’athérome","contenu":"<div class=\"notion-course\"><p>L'<span>athérome</span> = <strong>remaniement de l'intima</strong> des <strong><span class=\"nc-yellow_bg\">artères de gros et moyen calibre</span></strong> (aorte et ses branches), défini par une <strong>accumulation focale</strong> de plusieurs constituants.</p>\n      <p>Constituants accumulés dans l'<span>intima</span> :</p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">Lipides</span></span></li>\n        <li><span><span class=\"nc-red nc-bold\">Glucides</span> <span class=\"nc-red nc-bold\">complexes</span></span></li>\n        <li><span><span class=\"nc-red nc-bold\">Sang</span> et produits sanguins</span></li>\n        <li><span>Tissu <span class=\"nc-red nc-bold\">fibreux</span></span></li>\n        <li><span><span class=\"nc-red nc-bold\">Dépôts</span> <span class=\"nc-red nc-bold\">calcaires</span></span></li>\n      </ul>\n      <p>Des modifications de la <span>média</span> peuvent accompagner le remaniement de l'intima.</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'<span>athérome</span> touche les <strong><span class=\"nc-yellow_bg\">artères de gros et moyen calibre</span></strong> — jamais les artérioles ni les capillaires. La <span>lésion</span> est <strong>focale</strong> (plaques) et siège dans l'<strong>intima</strong>.\n      </div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"221-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition du malade polyathéromateux","contenu":"<div class=\"notion-course\"><p>Le <span>malade polyathéromateux</span> (= polyvasculaire) présente une atteinte athéromateuse d'<strong><span><span class=\"nc-red nc-bold\">≥ 2</span></span><span class=\"nc-red nc-bold\"> territoires artériels différents</span></strong>. Chaque atteinte peut être :</p>\n      <ul>\n        <li><strong>Symptomatique</strong> — ex. <span>claudication intermittente</span> des membres inférieurs chez un patient aux ATCD d'<span>IDM</span></li>\n        <li><strong>Asymptomatique mais significative</strong> — ex. <span><span class=\"nc-red nc-bold\">sténose carotidienne</span></span> asymptomatique à<span> 50 %</span> chez un patient porteur d'une <span class=\"nc-red nc-bold\">AOMI</span></li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Piège classique.</strong> Une simple <span>plaque non sténosante (&lt; 50 %)</span> et <strong>non compliquée</strong> ne suffit PAS à qualifier un patient de polyvasculaire — même si elle témoigne d'une <span>athérosclérose</span> débutante. Il faut une atteinte <strong>significative</strong> (sténose <span>≥ 50 %</span>) ou <strong>symptomatique</strong>.\n      </div>\n      <p>La <span>prévalence</span> du caractère polyvasculaire varie <strong>selon le siège de la 1<sup>re</sup> <span>lésion</span> devenue symptomatique</strong> :</p>\n      <table>\n        <thead><tr><th>1<sup>re</sup> lésion symptomatique</th><th>Atteinte d'un autre territoire retrouvée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Patient coronarien</span></strong></td>\n            <td><span><span class=\"nc-red nc-bold\">AOMI</span></span> (<span>20 %</span>) ; <span><span class=\"nc-red nc-bold\">sténose carotidienne</span></span> (<span>20 %</span>) ; <span><span class=\"nc-red nc-bold\">sténose des artères rénales</span></span> (<span>20 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Patient avec <span class=\"nc-red nc-bold\">AOMI</span>, <span class=\"nc-red nc-bold\">sténose carotidienne</span> ou <span class=\"nc-yellow_bg\">AAA</span></strong></td>\n            <td>Atteinte <span><span class=\"nc-red nc-bold\">coronarienne</span></span> dans <span>40-50 %</span> des cas</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Fréquence des atteintes associées selon la pathologie initiale (en %) :</p>\n      <table>\n        <thead><tr><th>Pathologie du patient</th><th>Coronaires</th><th>AOMI</th><th>Carotides</th><th>AAA</th><th><span class=\"nc-pink nc-bold\">Artères</span> rénales</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Coronaropathie</strong></td><td>—</td><td><span>19</span></td><td><span>20</span></td><td><span>3</span></td><td><span>18</span></td></tr>\n          <tr><td><strong>AOMI</strong></td><td><span>57</span></td><td>—</td><td><span>15</span></td><td><span>8,5</span></td><td><span>15</span></td></tr>\n          <tr><td><strong>Atteinte des TSA</strong></td><td><span>53</span></td><td><span>35</span></td><td>—</td><td><span>6</span></td><td><span>6</span></td></tr>\n          <tr><td><strong>AAA</strong></td><td><span>53</span></td><td><span>25</span></td><td><span>20</span></td><td>—</td><td><span>28</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Les patients atteints d'<strong><span class=\"nc-red nc-bold\">AOMI</span></strong> sont ceux qui ont le plus souvent une atteinte <strong>polyvasculaire</strong> associée. Toujours rechercher une <span>dysfonction érectile</span> : c'est un indicateur sentinelle de maladie artérielle, souvent tu par le patient.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 225 — Artériopathie oblitérante - anévrysme · 339 — <span>Syndrome coronarien</span> aiguë</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"221-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence et l’incidence de l’athérome (y compris atteintes infracliniques)","contenu":"<div class=\"notion-course\"><p>L'<span>athérome</span> débute <strong>très précocement</strong> — les <span><span class=\"nc-red\">stries</span> <span class=\"nc-red\">lipidiques</span></span> (premier <span>stade</span> lésionnel) sont retrouvées <strong>dès le jeune âge</strong> sur les autopsies. La maladie évolue ensuite silencieusement pendant des décennies (phase <strong>infraclinique</strong>) avant les premiers accidents.</p>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Tendance</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Incidence</span> — sexe</strong></td>\n            <td><span>3 à 5 fois</span> plus fréquente chez l'<strong>homme</strong> ; cette différence <strong>s'atténue avec l'âge</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span>Incidence</span> — femme</strong></td>\n            <td><span>Incidence</span> des <span>SCA</span> en <strong>augmentation chez la femme</strong>, par augmentation du <span>tabagisme</span> féminin</td>\n          </tr>\n          <tr>\n            <td><strong><span>Mortalité</span> cardiovasculaire</strong></td>\n            <td>Tendance à la <strong>baisse</strong> — progrès de la prise en charge et de la prévention</td>\n          </tr>\n          <tr>\n            <td><strong><span>Prévalence</span> des maladies CV</strong></td>\n            <td>En <strong>augmentation</strong> — vieillissement des populations + <span>réduction</span> de la <span>mortalité</span> (les patients vivent plus longtemps avec la maladie)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Incidence</span> des maladies CV</strong></td>\n            <td>En <strong>hausse</strong>, tirée par la progression du <span>diabète</span> et de l'<span>obésité</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Atteintes infracliniques.</strong> Une artère peut s'occlure <strong>progressivement et de façon asymptomatique</strong> grâce au <span class=\"nc-green nc-bold\">développement d'une </span><span><span class=\"nc-green nc-bold\">collatéralité</span></span> (ex. occlusion chronique d'une coronaire ou de la fémorale superficielle). L'étendue lésionnelle réelle est donc largement sous-estimée par la clinique.\n      </div><h4>Points de raisonnement et précautions</h4><ul><li>La fréquence varie selon l’âge, le territoire et la méthode de dépistage. L’athérosclérose infraclinique est bien plus fréquente que les accidents symptomatiques ; ne pas transformer une prévalence de plaques en incidence annuelle d’accidents.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"221-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes tendances de mortalité et morbidité de la cardiopathie ischémique, l’accident vasculaire cérébral (AVC), l’artériopathie oblitérante des membres inférieurs (AOMI), de l’anévrysme de l’aorte abdominale (causes de mortalité, influence de l’âge et du sexe, évolution dans le temps, gradient nord sud)","contenu":"<div class=\"notion-course\"><p>Les <strong>maladies cardiovasculaires</strong> liées à l'<span>athérome</span> dominent la <span>mortalité</span> mondiale. Les deux grandes causes de mortalité CV sont la <span><span class=\"nc-red_bg\">cardiopathie ischémique</span></span> et l'<span><span class=\"nc-red_bg\">AVC</span></span>.</p>\n      <table>\n        <thead><tr><th>Échelle</th><th>Place des maladies CV dans la mortalité</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Monde</strong></td><td><span>1<sup>re</sup> cause</span> de <span>mortalité</span></td></tr>\n          <tr><td><strong>France</strong></td><td><span>2<sup>e</sup> cause</span> de <span>mortalité</span>, après le <span>cancer</span> (forte baisse de la mortalité CV) — mais reste la <strong>1<sup>re</sup> cause chez la femme</strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Gradient nord-sud</strong> — la <span>mortalité</span> CV décroît du nord vers le sud :</p>\n      <table>\n        <thead><tr><th>Région</th><th>Mortalité cardiovasculaire</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red_bg\">Pays du </span><strong><span class=\"nc-red_bg\">nord et de l'est de l'Europe</span></strong></td><td>La plus <strong>élevée</strong></td></tr>\n          <tr><td><strong><span class=\"nc-orange_bg\">Amérique du Nord</span></strong></td><td><strong>Intermédiaire</strong></td></tr>\n          <tr><td><strong><span class=\"nc-green_bg\">Europe du Sud</span>, <span class=\"nc-green_bg\">Japon</span></strong></td><td>La plus <strong>faible</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <strong>France</strong> est l'un des pays d'Europe à la <span>mortalité</span> CV la plus faible. Le gradient nord-sud se retrouve <strong>aussi à l'échelle de la France</strong> (gradient intra-national), surtout pour la <span class=\"nc-red_bg\">cardiopathie </span><span><span class=\"nc-red_bg\">ischémique</span></span>.\n      </div>\n      <p><strong><span>Évolution</span> dans le temps</strong> : <strong><span class=\"nc-green_bg\">diminution</span></strong><span class=\"nc-green_bg\"> de l'</span><span><span class=\"nc-green_bg\">incidence</span></span><span class=\"nc-green_bg\"> des maladies athéromateuses dans les </span><strong><span class=\"nc-green_bg\">pays développés</span></strong>, mais <strong>augmentation</strong> dans les <strong>pays en voie de développement</strong>. Ces variations sont liées à la <strong>diversité des facteurs environnementaux et des habitudes alimentaires</strong> plutôt qu'à des différences génétiques (ex. risque CV accru chez les migrants asiatiques installés aux USA).</p>\n      <p><strong>Influence de l'âge et du sexe</strong> : nette prédominance masculine, atténuée avec l'âge ; <span>incidence</span> des <span>SCA</span> en hausse chez la femme par le <span>tabagisme</span> (cf. obj-2).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span>Syndrome coronarien</span> aiguë · 340 — <span>AVC</span> · 225 — Artériopathie oblitérante - anévrysme</em></p><h4>Points de raisonnement et précautions</h4><ul><li>Toujours préciser l’année, la population et le critère d’une statistique de mortalité. Les tendances de baisse liée à la prévention et aux traitements coexistent avec le vieillissement, le diabète et l’obésité ; le classement des causes de décès varie selon l’âge et le sexe.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"221-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de formation et l’évolution de la plaque d’athérome","contenu":"<div class=\"notion-course\"><p><strong>Objectif physiopathologique majeur</strong> (⭐⭐ au QCM). La formation d'une <span>plaque</span> suit une <strong>cascade en plusieurs étapes</strong>, débutant par l'accumulation de <span>LDL</span> dans la paroi artérielle.</p>\n      <p><strong>Formation de la <span>plaque</span> — cascade</strong></p>\n      <ol>\n        <li><strong>Dépôt</strong> des lipoprotéines athérogènes dans l'intima — principalement les <span>LDL</span></li>\n        <li><strong>Oxydation des <span>LDL</span></strong> dans la paroi, favorisée par un <strong>temps de séjour allongé</strong> et un <strong>environnement <span>inflammatoire</span> local</strong></li>\n        <li>Les <span>LDL oxydées</span> ne sont plus reconnues par le récepteur <span>LDL-R</span></li>\n        <li><strong>Recrutement de macrophages</strong> qui internalisent les <span>LDL</span> oxydées via les <span>récepteurs scavengers SR-A</span> (« éboueurs »)</li>\n        <li>Transformation des macrophages en <span>cellules spumeuses</span> (gorgées d'esters de <span>cholestérol</span>)</li>\n        <li><strong>Dysfonction endothéliale</strong> : baisse des capacités vasodilatatrices et antithrombotiques de l'endothélium, aggravée par le <strong><span class=\"nc-red\">tabac</span></strong> et les <span>LDL</span> oxydées</li>\n        <li><strong>Réaction <span>inflammatoire</span> auto-entretenue</strong> sécrétant des <span>métalloprotéases</span> destructrices de la matrice extracellulaire</li>\n        <li><strong>Migration des <span class=\"nc-red\">cellules musculaires lisses</span></strong> de la média vers la néo-intima</li>\n        <li>Sécrétion de facteurs de croissance, de <span>collagène</span> et de matrice → organisation de la <span>plaque</span></li>\n      </ol>\n      <p>La <span>plaque</span> constituée comporte deux composantes :</p>\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Centre lipidique</span></span> — <span class=\"nc-red\">nécrotique</span> ; contient <span class=\"nc-red\">stries</span> <span class=\"nc-red\">lipidiques</span>, <span class=\"nc-red\">cellules musculaires lisses</span> et <span class=\"nc-red\">cellules inflammatoires</span> (les <span class=\"nc-red\">stries</span> <span class=\"nc-red\">lipidiques</span> sont retrouvées dès le jeune âge)</li>\n        <li><span><span class=\"nc-blue_bg\">Chape fibreuse</span></span> — apparition tardive ; recouvre le <span class=\"nc-blue_bg\">centre lipidique</span> ; faite de <strong>collagène de type I</strong></li>\n      </ul>\n      <p><strong><span>Évolution</span> de la <span>plaque</span></strong></p>\n      <table>\n        <thead><tr><th>Évolution</th><th>Mécanisme et conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Rupture de plaque</span></td>\n            <td><span>Érosion</span> ou déchirure de la <span class=\"nc-blue_bg\">chape fibreuse</span> → <strong>formation immédiate d'un <span>thrombus</span></strong> → accidents aigus (<span>SCA</span>, <span>AVC</span>) par <span>réduction</span>/obstruction de la lumière ; le <span>thrombus</span> peut se fragmenter et donner des <strong>embolies</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Progression de <span>plaque</span></strong></td>\n            <td>Augmentation de volume (composante lipidique + matrice) ; progression surtout <strong>par poussées</strong> lors des ruptures (incorporation de matériel <span>thrombotique</span>) ; une <span><span class=\"nc-red_bg\">hémorragie intraplaque</span></span> augmente brutalement le volume et peut rompre la chape</td>\n          </tr>\n          <tr>\n            <td><strong>Sténose — remodelage</strong></td>\n            <td><strong><span class=\"nc-green_bg\">Remodelage compensateur</span> :</strong> le <span>diamètre</span> s'élargit pour préserver la lumière artérielle<br><strong>Remodelage constrictif :</strong> le diamètre se réduit et majore la sténose en regard de la <span>plaque</span></td>\n          </tr>\n          <tr>\n            <td><strong>Anévrisme</strong></td>\n            <td>L'<span>athérome</span> peut altérer la structure pariétale et détruire la matrice extracellulaire → <strong>dilatation anévrismale</strong> (mais tous les anévrismes ne sont pas d'origine athéromateuse)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> La <strong>gravité d'un accident aigu n'est pas proportionnelle</strong> à l'ancienneté ni à l'étendue de l'<span>athérome</span> : la <span>rupture</span> d'une <span>plaque</span> <strong>jeune</strong> peut causer un <span>infarctus</span> ou une <span>mort subite</span>, tandis qu'une artère peut s'occlure <strong>sans symptôme</strong> grâce à la collatéralité.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span>Syndrome coronarien</span> aiguë · 340 — <span>AVC</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"221-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les particularités de la physiopathologie de l’athérome (cibles et intervenants)","contenu":"<div class=\"notion-course\"><p>La <span>physiopathologie</span> de l'<span>athérome</span> met en jeu des <strong>intervenants</strong> cellulaires et moléculaires précis ; chacun constitue une <strong>cible thérapeutique</strong> potentielle.</p>\n      <p><strong>Intervenants de l'athérogenèse</strong></p>\n      <table>\n        <thead><tr><th>Intervenant</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><span>LDL</span> / <span>LDL</span> oxydées</td><td>Lipoprotéines athérogènes ; substrat initial de la <span>plaque</span></td></tr>\n          <tr><td><span>Macrophages</span> → cellules spumeuses</td><td>Internalisent les <span>LDL</span> oxydées (récepteurs scavengers SR-A) ; entretiennent l'inflammation</td></tr>\n          <tr><td><span>Endothélium</span></td><td>Sa dysfonction (perte des propriétés vasodilatatrices et antithrombotiques) initie et entretient la <span>lésion</span></td></tr>\n          <tr><td><span><span class=\"nc-red\">Cellules musculaires lisses</span></span></td><td>Migrent de la média vers l'intima ; synthétisent collagène et matrice (<span class=\"nc-blue_bg\">chape fibreuse</span>)</td></tr>\n          <tr><td><span>Métalloprotéases</span> et inflammation</td><td>Détruisent la matrice extracellulaire ; fragilisent la chape → risque de <span>rupture</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cibles thérapeutiques — points d'impact des traitements</strong></p>\n      <table>\n        <thead><tr><th>Cible</th><th>Moyen d'action</th></tr></thead>\n        <tbody>\n          <tr><td>Dysfonction endothéliale</td><td>Suppression / traitement de <strong>tous les <span>facteurs de risque</span> modifiables</strong></td></tr>\n          <tr><td>Accumulation des <span>LDL</span></td><td>Régime alimentaire ; <span><span class=\"nc-pink nc-bold\">statines</span></span> et autres hypolipémiants</td></tr>\n          <tr><td>Stabilisation des plaques</td><td>Diminuer le risque de <span>rupture</span> — propriété propre des <span><span class=\"nc-pink nc-bold\">statines</span></span></td></tr>\n          <tr><td>Régression du volume de <span>plaque</span></td><td><span><span class=\"nc-pink nc-bold\">Statines</span> à forte dose</span>, si besoin associées à l'<span>ézétimibe</span> ou aux <span>anti-PCSK9</span></td></tr>\n          <tr><td>Inflammation</td><td><span><span class=\"nc-pink_bg\">Aspirine</span></span> ; <span>statines</span></td></tr>\n          <tr><td>Contraintes mécaniques</td><td>Traitements <span>antihypertenseurs</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Les <span><span class=\"nc-pink nc-bold\">statines</span></span> agissent sur <strong>plusieurs cibles à la fois</strong> : baisse des <span>LDL</span>, stabilisation de la <span>plaque</span>, régression du volume, effet anti-<span>inflammatoire</span> — d'où leur place centrale.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 223 — <span>Dyslipidémie</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"221-7","rang":"A","rubrique":"Diagnostic","titre":"Connaître les localisations préférentielles de la maladie athéromateuse","contenu":"<div class=\"notion-course\"><p>L'<span>athérome</span> touche les <strong><span class=\"nc-yellow_bg\">artères de gros et moyen calibre</span></strong> (aorte et ses branches). Les plaques se forment préférentiellement à proximité des <strong>flux artériels turbulents</strong> : <span>ostiums</span>, <span>bifurcations</span>, zones de <span>contrainte mécanique</span>.</p>\n      <p>Six localisations principales, classées par fréquence et conséquences pathologiques :</p>\n      <table>\n        <thead><tr><th>Localisation</th><th>Conséquence clinique</th></tr></thead>\n        <tbody>\n          <tr><td>1 · Artères <strong><span class=\"nc-pink nc-bold\">carotidiennes</span></strong></td><td><span>AVC</span></td></tr>\n          <tr><td>2 · <span class=\"nc-pink nc-bold\">Artères</span> <strong><span class=\"nc-pink nc-bold\">coronariennes</span></strong></td><td><span>Cardiopathies ischémiques</span></td></tr>\n          <tr><td>3 · <strong><span class=\"nc-pink nc-bold\">Crosse de l'aorte</span></strong></td><td><span>AVC</span> ; <span>anévrisme de l'aorte abdominale</span></td></tr>\n          <tr><td>4 · <span class=\"nc-pink nc-bold\">Artères</span> <strong><span class=\"nc-pink nc-bold\">rénales</span></strong></td><td><span>HTA</span> ; <span>insuffisance rénale</span> (néphropathie vasculaire)</td></tr>\n          <tr><td>5 · <span class=\"nc-pink nc-bold\">Artères</span> <strong><span class=\"nc-pink nc-bold\">digestives</span></strong></td><td><span>Ischémie mésentérique</span></td></tr>\n          <tr><td>6 · <span class=\"nc-pink nc-bold\">Artères des </span><strong><span class=\"nc-pink nc-bold\">membres inférieurs</span></strong></td><td><span>Artériopathie oblitérante (AOMI)</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Les réductions successives de lumière donnent une <strong>ischémie chronique stable</strong> (<span>angor</span> d'effort, <span>claudication</span> intermittente, claudication digestive postprandiale). Les ruptures de <span>plaque</span> donnent des <strong>accidents aigus</strong> dépendant du territoire (<span>SCA</span>, <span>AVC</span> <span>ischémique</span>, <span>ischémie aiguë</span> de membre).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span>Syndrome coronarien</span> aiguë · 340 — <span>AVC</span> · 224 — <span>HTA</span> · 225 — Artériopathie oblitérante - anévrysme · 264 — <span>Insuffisance rénale</span> chronique</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"221-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration en imagerie devant une maladie athéromateuse","contenu":"<div class=\"notion-course\"><ul><li>L’interrogatoire et l’examen cherchent une atteinte coronaire, cérébrovasculaire, des membres inférieurs ou aortique. Une exploration est choisie parce que son résultat peut modifier la prise en charge.</li><li>AOMI suspectée : IPS au repos puis écho-Doppler ; si IPS incompressible, pression d’orteil. Angioscanner ou angio-IRM surtout pour préciser l’anatomie avant revascularisation.</li><li>AIT ou AVC : urgence neurovasculaire et imagerie cérébrale/vasculaire adaptée. Le Doppler carotidien n’est pas un dépistage universel de toute personne asymptomatique.</li><li>Symptômes coronaires : ECG et stratégie dédiée ; urgence avec troponines si SCA, exploration fonctionnelle ou anatomique selon la probabilité si syndrome chronique.</li><li><span class=\"nc-yellow_bg\">AAA</span> : échographie pour dépistage ciblé et mesure ; angioscanner pour complication ou préparation du traitement. Une exploration aortique doit préciser le segment étudié.</li><li>Ne pas confondre bilan ciblé du polyathéromateux et multiplication <span class=\"nc-green nc-bold\">systématique</span> d’examens sans conséquence thérapeutique.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"221-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge du malade polyathéromateux","contenu":"<div class=\"notion-course\"><ul><li>Prévention secondaire : sevrage tabagique, activité physique/réadaptation, alimentation adaptée, contrôle de la PA et du diabète, traitement hypolipémiant intensif et observance.</li><li>Statine à intensité adaptée, puis associations selon le LDL obtenu et le risque. Chez le patient à très haut risque, repère européen : LDL &lt; 0,55 g/L et baisse d’au moins 50 % par rapport au niveau initial.</li><li>Antithrombotiques selon le territoire, les antécédents, une éventuelle revascularisation et le risque hémorragique ; pas de cumul <span class=\"nc-green nc-bold\">systématique</span>. <span class=\"nc-pink_bg\">Aspirine</span> généralement à faible dose ou <span class=\"nc-pink_bg\">clopidogrel</span> selon l’indication.</li><li><span class=\"nc-pink_bg\">IEC/ARA2</span> et bêtabloquant selon les indications : HTA, insuffisance cardiaque, coronaropathie symptomatique, contexte post-infarctus ou trouble du rythme. Le moyen mnémotechnique BASI ne constitue pas une ordonnance universelle.</li><li>Revasculariser selon symptômes, anatomie et bénéfice attendu. Une <span class=\"nc-red nc-bold\">sténose carotidienne</span> asymptomatique ne relève pas d’une intervention sur le seul chiffre de 60 % : décision spécialisée avec traitement médical optimal, risque opératoire et espérance de vie.</li><li>Suivi coordonné : symptômes d’alerte, tolérance, bilan lipidique et rénal selon traitements, pieds si AOMI/diabète, vaccination et réadaptation selon le contexte.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"221-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de l’éducation thérapeutique du patient athéromateux","contenu":"<div class=\"notion-course\"><p>L'<span>éducation thérapeutique</span> du patient <span>athéromateux</span> fait partie intégrante des moyens thérapeutiques, au même titre que le traitement <span>médicamenteux</span>. Elle vise à rendre le patient acteur du contrôle de sa maladie au long cours.</p>\n      <p>Axes principaux issus des fiches sources :</p>\n      <ul>\n        <li><strong>Arrêt du tabac</strong> — mesure prioritaire et <span class=\"nc-green nc-bold\">systématique</span></li>\n        <li><strong><span>Règles hygiéno-diététiques</span></strong> — alimentation, contrôle pondéral</li>\n        <li><strong>Activité physique</strong> régulière</li>\n        <li><strong>Contrôle des <span>facteurs de risque</span></strong> modifiables, commun à tous les territoires atteints</li>\n        <li><strong>Observance</strong> du traitement de <span>prévention secondaire</span> (<span><span class=\"nc-pink_bg\">aspirine</span></span>, <span>statine</span>, <span><span class=\"nc-pink_bg\">IEC/ARA2</span></span>)</li>\n        <li><strong><span>Suivi</span></strong> : examen clinique <strong><span class=\"nc-pink nc-bold\">annuel</span></strong>, explorations complémentaires au cas par cas</li>\n        <li><strong><span>Entretiens motivationnels</span> répétés</strong> — outil-clé LiSA pour obtenir et maintenir les changements de mode de vie (sevrage tabagique, alimentation, activité physique) et vérifier l'adhésion aux traitements</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Reconnaître les signes d'appel des complications.</strong> Le patient doit savoir repérer les signes d'alerte imposant une <strong>consultation en <span>urgence</span></strong> :\n        <ul>\n          <li><span>Douleur thoracique</span> → suspicion de <span>SCA</span></li>\n          <li><span>Déficit neurologique brutal</span> → suspicion d'<span>AVC</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 223 — <span>Dyslipidémie</span></em></p><h4>Points de raisonnement et précautions</h4><ul><li>Construire avec le patient un objectif réalisable, vérifier sa compréhension par reformulation et programmer une réévaluation. Douleur thoracique persistante, déficit neurologique brutal ou membre froid douloureux : recours immédiat aux urgences.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Athérome (221)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 221</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Prévention cardiovasculaire, 2021</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Raisonner avant le chiffre","contenu":"<div class=\"notion-course\"><p>Interpréter un seuil avec le tableau clinique, le référentiel et les unités ; une complication aiguë impose de réévaluer immédiatement la stratégie.</p></div>"},{"type":"piege","titre":"Source et synthèse","contenu":"<div class=\"notion-course\"><p>Les schémas du collège restent accessibles. Les arbres ATLAS et leurs compléments sont explicitement identifiés et reliés aux objectifs concernés.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Rechercher les signes de gravité puis préciser la probabilité et le mécanisme.</li><li>Choisir les examens capables de modifier la décision et confronter les résultats à la clinique.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Adapter la prise en charge à l’urgence, au terrain, aux contre-indications et aux préférences.</li><li>Prévoir surveillance, éducation et réévaluation ; utiliser les arbres reliés au cours.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.sfcardio.fr/publication/chapitre-01-item-221-atherome-epidemiologie-et-physiopathologie-le-malade-polyatheromateux/","label":"CNEC · Item 221 ↗"},{"href":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/cvd-prevention/","label":"ESC · Prévention cardiovasculaire, 2021 ↗"}],"cards":[{"i":"286f60f2bd36","n":221,"o":"221-1","u":"Définition","t":"Connaître la définition de l’athérome","q":"Quelle est la définition de l'athérome ?","a":"<div class=\"notion-course\"><p>L'athérome est un <strong>remaniement de l'intima</strong> des <span class=\"nc-yellow_bg\">artères de </span><strong><span class=\"nc-yellow_bg\">gros et moyen calibre</span></strong> (aorte et ses branches), défini par une <strong>accumulation focale</strong> de plusieurs constituants.</p></div>"},{"i":"ca6a242a9dc7","n":221,"o":"221-1","u":"Définition","t":"Connaître la définition de l’athérome","q":"Quelles sont les caractéristiques principales de la localisation de l'athérome ?","a":"<div class=\"notion-course\"><ul><li>Il touche les <span class=\"nc-yellow_bg\">artères de </span><strong><span class=\"nc-yellow_bg\">gros et moyen calibre</span></strong>, <strong>jamais les artérioles ni les capillaires</strong>.</li><li>La lésion est <strong>focale</strong> (plaques).</li><li>Elle siège dans l'<strong>intima</strong>.</li></ul></div>"},{"i":"eca9817e28e8","n":221,"o":"221-1","u":"Définition","t":"Connaître la définition de l’athérome","q":"Quels sont les constituants accumulés dans l'intima lors de l'athérome ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-red nc-bold\">Lipides</span></strong></li><li><strong><span class=\"nc-red nc-bold\">Glucides</span> <span class=\"nc-red nc-bold\">complexes</span></strong></li><li><strong><span class=\"nc-red nc-bold\">Sang</span> et produits sanguins</strong></li><li><strong>Tissu <span class=\"nc-red nc-bold\">fibreux</span></strong></li><li><strong><span class=\"nc-red nc-bold\">Dépôts</span> <span class=\"nc-red nc-bold\">calcaires</span></strong></li></ul></div>"},{"i":"0700b43729ea","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Chez quel type de patient doit-on particulièrement rechercher une atteinte polyvasculaire associée ?","a":"<div class=\"notion-course\"><p>Les patients atteints d'<strong>artériopathie oblitérante des membres inférieurs (<span class=\"nc-red nc-bold\">AOMI</span>)</strong> sont ceux qui présentent le plus souvent une atteinte polyvasculaire associée.</p></div>"},{"i":"4fe465b59bb2","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Quelle est la définition d'un malade polyathéromateux ?","a":"<div class=\"notion-course\"><p>Un malade polyathéromateux, également appelé polyvasculaire, est un patient qui présente une <strong>atteinte athéromateuse d'au moins deux territoires artériels différents</strong>.</p></div>"},{"i":"9b4dadf0a1d0","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Quel signe clinique spécifique doit être recherché systématiquement chez un patient avec de l'athérosclérose, même s'il est souvent tu ?","a":"<div class=\"notion-course\"><p>Il faut toujours rechercher une <strong>dysfonction érectile</strong>, car c'est un indicateur sentinelle de maladie artérielle, souvent non rapporté spontanément par le patient.</p></div>"},{"i":"9e8343668410","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Comment caractérise-t-on une atteinte artérielle pour définir un patient comme polyvasculaire ?","a":"<div class=\"notion-course\"><ul><li>L'atteinte peut être <strong>symptomatique</strong> (par exemple, une claudication intermittente des membres inférieurs).</li><li>Elle peut être <strong>asymptomatique mais significative</strong>, ce qui correspond à une sténose d'au moins <strong>50%</strong>.</li></ul></div>"},{"i":"d2e8b35cde8e","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Qu'est-ce qui ne suffit pas à qualifier un patient de polyvasculaire ?","a":"<div class=\"notion-course\"><p>La présence d'une simple <strong>plaque non sténosante (&lt; 50%)</strong> et non compliquée ne suffit pas à qualifier un patient de polyvasculaire, même si elle témoigne d'une athérosclérose débutante. Il faut une atteinte significative (sténose ≥ 50%) ou symptomatique.</p></div>"},{"i":"429009706349","n":221,"o":"221-7","u":"Diagnostic","t":"Connaître les localisations préférentielles de la maladie athéromateuse","q":"Quelles sont les six localisations principales de la maladie athéromateuse et leurs conséquences cliniques associées ?","a":"<div class=\"notion-course\"><p>Les six localisations principales de la maladie athéromateuse et leurs conséquences cliniques sont :</p><ul><li><strong><span class=\"nc-pink nc-bold\">Artères</span> <span class=\"nc-pink nc-bold\">carotidiennes</span></strong> : Accident Vasculaire Cérébral (AVC).</li><li><strong><span class=\"nc-pink nc-bold\">Artères</span> <span class=\"nc-pink nc-bold\">coronariennes</span></strong> : Cardiopathies ischémiques (Syndrome Coronaire Aigu - SCA).</li><li><strong><span class=\"nc-pink nc-bold\">Crosse de l'aorte</span></strong> : AVC ou anévrisme de l'aorte abdominale.</li><li><strong><span class=\"nc-pink nc-bold\">Artères</span> <span class=\"nc-pink nc-bold\">rénales</span></strong> : Hypertension Artérielle (HTA) ou insuffisance rénale (néphropathie vasculaire).</li><li><strong><span class=\"nc-pink nc-bold\">Artères</span> <span class=\"nc-pink nc-bold\">digestives</span></strong> : Ischémie mésentérique.</li><li><strong><span class=\"nc-pink nc-bold\">Artères des membres inférieurs</span></strong> : Artériopathie Oblitérente des Membres Inférieurs (AOMI).</li></ul></div>"},{"i":"a08cc6aed7a7","n":221,"o":"221-7","u":"Diagnostic","t":"Connaître les localisations préférentielles de la maladie athéromateuse","q":"Où se forment préférentiellement les plaques d'athérome ?","a":"<div class=\"notion-course\"><p>Les plaques d'athérome se forment préférentiellement dans les zones de <strong>flux artériels turbulents</strong>, telles que :</p><ul><li>Les <strong>ostiums</strong>.</li><li>Les <strong>bifurcations</strong>.</li><li>Les zones de forte <strong>contrainte mécanique</strong>.</li></ul></div>"},{"i":"b094c501eef2","n":221,"o":"221-7","u":"Diagnostic","t":"Connaître les localisations préférentielles de la maladie athéromateuse","q":"Quels types d'artères sont principalement touchés par la maladie athéromateuse ?","a":"<div class=\"notion-course\"><p>La maladie athéromateuse touche préférentiellement les <strong><span class=\"nc-yellow_bg\">artères de gros et moyen calibre</span></strong>, notamment <strong>l'aorte et ses branches</strong>.</p></div>"},{"i":"254dceb83828","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Quelles sont les indications chirurgicales ou d'endartériectomie pour une sténose carotidienne chez un patient polyathéromateux ?","a":"<div class=\"notion-course\"><ul><li>Revasculariser selon symptômes, anatomie et bénéfice attendu. Une <span class=\"nc-red nc-bold\">sténose carotidienne</span> asymptomatique ne relève pas d’une intervention sur le seul chiffre de 60 % : décision spécialisée avec traitement médical optimal, risque opératoire et espérance de vie.</li></ul></div>"},{"i":"36d48eb8ea28","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Quel est l'objectif majeur de la prise en charge d'un patient polyathéromateux ?","a":"<div class=\"notion-course\"><ul><li>Prévention secondaire : sevrage tabagique, activité physique/réadaptation, alimentation adaptée, contrôle de la PA et du diabète, traitement hypolipémiant intensif et observance.</li></ul></div>"},{"i":"5377f4ecfbb1","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Quelles sont les mesures non médicamenteuses systématiques dans la prise en charge du patient polyathéromateux ?","a":"<div class=\"notion-course\"><ul><li>Prévention secondaire : sevrage tabagique, activité physique/réadaptation, alimentation adaptée, contrôle de la PA et du diabète, traitement hypolipémiant intensif et observance.</li></ul></div>"},{"i":"57d034799c8f","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Quelle est la place des bêta-bloquants dans la prise en charge du patient polyathéromateux ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink_bg\">IEC/ARA2</span> et bêtabloquant selon les indications : HTA, insuffisance cardiaque, coronaropathie symptomatique, contexte post-infarctus ou trouble du rythme. Le moyen mnémotechnique BASI ne constitue pas une ordonnance universelle.</li></ul></div>"},{"i":"ab31c4f75533","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Comment individualiser les médicaments chez le patient polyathéromateux ?","a":"<div class=\"notion-course\"><ul><li>Statine à intensité adaptée, puis associations selon le LDL obtenu et le risque. Chez le patient à très haut risque, repère européen : LDL &lt; 0,55 g/L et baisse d’au moins 50 % par rapport au niveau initial.</li><li>Antithrombotiques selon le territoire, les antécédents, une éventuelle revascularisation et le risque hémorragique ; pas de cumul <span class=\"nc-green nc-bold\">systématique</span>. <span class=\"nc-pink_bg\">Aspirine</span> généralement à faible dose ou <span class=\"nc-pink_bg\">clopidogrel</span> selon l’indication.</li><li><span class=\"nc-pink_bg\">IEC/ARA2</span> et bêtabloquant selon les indications : HTA, insuffisance cardiaque, coronaropathie symptomatique, contexte post-infarctus ou trouble du rythme. Le moyen mnémotechnique BASI ne constitue pas une ordonnance universelle.</li></ul></div>"},{"i":"d722aeb150be","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Comment évalue-t-on l'extension de l'athérosclérose chez un patient polyathéromateux ?","a":"<div class=\"notion-course\"><ul><li>L’interrogatoire et l’examen cherchent une atteinte coronaire, cérébrovasculaire, des membres inférieurs ou aortique. Une exploration est choisie parce que son résultat peut modifier la prise en charge.</li><li>AOMI suspectée : IPS au repos puis écho-Doppler ; si IPS incompressible, pression d’orteil. Angioscanner ou angio-IRM surtout pour préciser l’anatomie avant revascularisation.</li><li>AIT ou AVC : urgence neurovasculaire et imagerie cérébrale/vasculaire adaptée. Le Doppler carotidien n’est pas un dépistage universel de toute personne asymptomatique.</li><li>Symptômes coronaires : ECG et stratégie dédiée ; urgence avec troponines si SCA, exploration fonctionnelle ou anatomique selon la probabilité si syndrome chronique.</li><li><span class=\"nc-yellow_bg\">AAA</span> : échographie pour dépistage ciblé et mesure ; angioscanner pour complication ou préparation du traitement. Une exploration aortique doit préciser le segment étudié.</li></ul></div>"},{"i":"00397691cc6c","n":221,"o":"221-3","u":"Epidémiologie","t":"Connaître la prévalence et l’incidence de l’athérome (y compris atteintes infracliniques)","q":"Quels sont les points clés concernant la prévalence et l’incidence de l’athérome (y compris atteintes infracliniques) ?","a":"<div class=\"notion-course\"><ul><li>L'<span>athérome</span> débute <strong>très précocement</strong> — les <span><span class=\"nc-red\"><span class=\"nc-red\">stries</span></span> <span class=\"nc-red\"><span class=\"nc-red\">lipidiques</span></span></span> (premier <span>stade</span> lésionnel) sont retrouvées <strong>dès le jeune âge</strong> sur les autopsies. La maladie évolue ensuite silencieusement pendant des décennies (phase <strong>infraclinique</strong>) avant les premiers accidents.</li><li>La fréquence varie selon l’âge, le territoire et la méthode de dépistage. L’athérosclérose infraclinique est bien plus fréquente que les accidents symptomatiques ; ne pas transformer une prévalence de plaques en incidence annuelle d’accidents.</li></ul></div>"},{"i":"73df1c2889f1","n":221,"o":"221-4","u":"Epidémiologie","t":"Connaître les grandes tendances de mortalité et morbidité de la cardiopathie ischémique, l’accident vasculaire cérébral (AVC), l’artériopathie oblitérante des membres inférieurs (AOMI), de l’anévrysme de l’aorte abdominale (causes de mortalité, influence de l’âge et du sexe, évolution dans le temps, gradient nord sud)","q":"Quels sont les points clés concernant les grandes tendances de mortalité et morbidité de la cardiopathie ischémique, l’accident vasculaire cérébral (AVC), l’artériopathie oblitérante des membres inférieurs (AOMI), de l’anévrysme de l’aorte abdominale (causes de mortalité, influence de l’âge et du sexe, évolution dans le temps, gradient nord sud) ?","a":"<div class=\"notion-course\"><ul><li>Les <strong>maladies cardiovasculaires</strong> liées à l'<span>athérome</span> dominent la <span>mortalité</span> mondiale. Les deux grandes causes de mortalité CV sont la <span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">cardiopathie ischémique</span></span></span> et l'<span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">AVC</span></span></span>.</li><li><strong>Gradient nord-sud</strong> — la <span>mortalité</span> CV décroît du nord vers le sud :</li><li><strong><span>Évolution</span> dans le temps</strong> : <strong><span class=\"nc-green_bg\"><span class=\"nc-green_bg\">diminution</span></span></strong><span class=\"nc-green_bg\"><span class=\"nc-green_bg\"> de l'</span></span><span><span class=\"nc-green_bg\"><span class=\"nc-green_bg\">incidence</span></span></span><span class=\"nc-green_bg\"><span class=\"nc-green_bg\"> des maladies athéromateuses dans les </span></span><strong><span class=\"nc-green_bg\"><span class=\"nc-green_bg\">pays développés</span></span></strong>, mais <strong>augmentation</strong> dans les <strong>pays en voie de développement</strong>. Ces variations sont liées à la <strong>diversité des facteurs environnementaux et des habitudes alimentaires</strong> plutôt qu'à des différences génétiques (ex. risque CV accru chez les migrants asiatiques installés aux USA).</li><li><strong>Influence de l'âge et du sexe</strong> : nette prédominance masculine, atténuée avec l'âge ; <span>incidence</span> des <span>SCA</span> en hausse chez la femme par le <span>tabagisme</span> (cf. obj-2).</li></ul></div>"},{"i":"0cb0323355ba","n":221,"o":"221-5","u":"Physiopathologie","t":"Connaître les mécanismes de formation et l’évolution de la plaque d’athérome","q":"Quels sont les points clés concernant les mécanismes de formation et l’évolution de la plaque d’athérome ?","a":"<div class=\"notion-course\"><ul><li><strong>Objectif physiopathologique majeur</strong> (⭐⭐ au QCM). La formation d'une <span>plaque</span> suit une <strong>cascade en plusieurs étapes</strong>, débutant par l'accumulation de <span>LDL</span> dans la paroi artérielle.</li><li><strong>Dépôt</strong> des lipoprotéines athérogènes dans l'intima — principalement les <span>LDL</span></li><li><strong>Oxydation des <span>LDL</span></strong> dans la paroi, favorisée par un <strong>temps de séjour allongé</strong> et un <strong>environnement <span>inflammatoire</span> local</strong></li><li>Les <span>LDL oxydées</span> ne sont plus reconnues par le récepteur <span>LDL-R</span></li></ul></div>"},{"i":"fe9b2084936c","n":221,"o":"221-6","u":"Physiopathologie","t":"Connaître les particularités de la physiopathologie de l’athérome (cibles et intervenants)","q":"Quels sont les points clés concernant les particularités de la physiopathologie de l’athérome (cibles et intervenants) ?","a":"<div class=\"notion-course\"><ul><li>La <span>physiopathologie</span> de l'<span>athérome</span> met en jeu des <strong>intervenants</strong> cellulaires et moléculaires précis ; chacun constitue une <strong>cible thérapeutique</strong> potentielle.</li><li><strong>Cibles thérapeutiques — points d'impact des traitements</strong></li><li><em>📎 Items liés : 222 — FDR cardiovasculaire · 223 — <span>Dyslipidémie</span></em></li></ul></div>"},{"i":"1e5ad5c89ec4","n":221,"o":"221-8","u":"Examens complémentaires","t":"Connaître la stratégie d’exploration en imagerie devant une maladie athéromateuse","q":"Quels sont les points clés concernant la stratégie d’exploration en imagerie devant une maladie athéromateuse ?","a":"<div class=\"notion-course\"><ul><li>L’interrogatoire et l’examen cherchent une atteinte coronaire, cérébrovasculaire, des membres inférieurs ou aortique. Une exploration est choisie parce que son résultat peut modifier la prise en charge.</li><li>AOMI suspectée : IPS au repos puis écho-Doppler ; si IPS incompressible, pression d’orteil. Angioscanner ou angio-IRM surtout pour préciser l’anatomie avant revascularisation.</li><li>AIT ou AVC : urgence neurovasculaire et imagerie cérébrale/vasculaire adaptée. Le Doppler carotidien n’est pas un dépistage universel de toute personne asymptomatique.</li><li>Symptômes coronaires : ECG et stratégie dédiée ; urgence avec troponines si SCA, exploration fonctionnelle ou anatomique selon la probabilité si syndrome chronique.</li></ul></div>"},{"i":"3fe69950baad","n":221,"o":"221-10","u":"Prise en charge","t":"Connaître les principes de l’éducation thérapeutique du patient athéromateux","q":"Quels sont les points clés concernant les principes de l’éducation thérapeutique du patient athéromateux ?","a":"<div class=\"notion-course\"><ul><li>L'<span>éducation thérapeutique</span> du patient <span>athéromateux</span> fait partie intégrante des moyens thérapeutiques, au même titre que le traitement <span>médicamenteux</span>. Elle vise à rendre le patient acteur du contrôle de sa maladie au long cours.</li><li>Axes principaux issus des fiches sources :</li><li><strong>Arrêt du tabac</strong> — mesure prioritaire et <span class=\"nc-green nc-bold\"><span class=\"nc-green nc-bold\">systématique</span></span></li><li><strong><span>Règles hygiéno-diététiques</span></strong> — alimentation, contrôle pondéral</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181b49c2bcf6d255ce408?pvs=204","reviewedAt":"2026-10-15","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif."},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Événement aigu évocateur ?","detail":"<ul><li>Coronarien, neurologique, membre froid ou douleur aortique.</li></ul>","branches":[{"label":"Oui","to":"aigu"},{"label":"Non","to":"extension"}]},{"id":"aigu","kind":"urgent","label":"Filière urgente du territoire atteint","detail":"<ul><li>Ne pas attendre un bilan de toutes les localisations.</li></ul>","branches":[]},{"id":"extension","kind":"decision","label":"Symptôme ou examen orientant ?","detail":"<ul><li>La maladie peut être infraclinique ; examen des territoires et facteurs de risque.</li></ul>","branches":[{"label":"Oui","to":"imagerie"},{"label":"Non","to":"risque"}]},{"id":"imagerie","kind":"decision","label":"Imagerie ciblée utile à la décision","detail":"<ul><li>Doppler/IPS, exploration coronaire, neurovasculaire ou aortique selon contexte.</li></ul>","branches":[{"label":"Prévention commune","to":"risque"}]},{"id":"risque","kind":"decision","label":"Maladie athéroscléreuse établie ?","detail":"<ul><li>Ne pas utiliser SCORE2 pour remplacer la prévention secondaire.</li></ul>","branches":[{"label":"Oui","to":"secondaire"},{"label":"Non","to":"primaire"}]},{"id":"secondaire","kind":"finish","label":"Prévention secondaire et traitements adaptés","detail":"<ul><li>Lipides, PA, diabète, tabac ; antithrombotiques selon indication.</li></ul>","branches":[]},{"id":"primaire","kind":"finish","label":"Évaluer le risque et décider avec le patient","detail":"<ul><li>Mode de vie, facteurs et suivi ; dépistage ciblé, sans examens systématiques inutiles.</li></ul>","branches":[]}]}};
